from pathlib import Path
from zipfile import ZipFile, ZIP_DEFLATED
from xml.sax.saxutils import escape
import json

import pandas as pd
from clean_data import load_and_clean


BASE = Path(__file__).resolve().parent
OUT = BASE / "Student_Dropout_Early_Warning_Project_Report.docx"
TEMP = BASE / "_report_build"


def run_info():
    original, quality = load_and_clean(BASE / "data.csv")
    oulad = pd.read_csv(BASE / "oulad_student_level.csv")
    labels = original["Target"].value_counts()
    ou_labels = oulad["final_result"].value_counts()
    return original, oulad, quality, labels, ou_labels


def p(text="", style=None):
    style_xml = f'<w:pStyle w:val="{style}"/>' if style else ""
    return f'<w:p><w:pPr>{style_xml}</w:pPr><w:r><w:t xml:space="preserve">{escape(str(text))}</w:t></w:r></w:p>'


def rich_p(parts, style=None):
    style_xml = f'<w:pStyle w:val="{style}"/>' if style else ""
    runs = "".join(f'<w:r><w:rPr>{"<w:b/>" if bold else ""}</w:rPr><w:t xml:space="preserve">{escape(text)}</w:t></w:r>' for text, bold in parts)
    return f'<w:p><w:pPr>{style_xml}</w:pPr>{runs}</w:p>'


def table(rows, widths=None):
    out = ['<w:tbl><w:tblPr><w:tblBorders>' + ''.join(f'<w:{edge} w:val="single" w:sz="4" w:space="0" w:color="D9A28E"/>' for edge in ('top','left','bottom','right','insideH','insideV')) + '</w:tblBorders><w:tblW w:w="0" w:type="auto"/></w:tblPr>']
    for ridx, row in enumerate(rows):
        out.append('<w:tr>')
        for val in row:
            fill = '<w:shd w:fill="FFE0D2"/>' if ridx == 0 else ''
            out.append(f'<w:tc><w:tcPr>{fill}<w:tcW w:w="2400" w:type="dxa"/></w:tcPr>{rich_p([(str(val), ridx == 0)])}</w:tc>')
        out.append('</w:tr>')
    out.append('</w:tbl>')
    return ''.join(out)


def bullet(text):
    return rich_p([("•  " + text, False)])


def build_body(original, oulad, quality, labels, ou_labels):
    orig_missing = int(original.isna().sum().sum())
    body = []
    body += [p("STUDENT DROPOUT EARLY-WARNING MODEL", "Title"),
             p("A two-stage, two-dataset machine-learning study with an interactive staff decision-support prototype", "Subtitle"),
             p("Project report | Prepared from the supplied source code and data | Performance results are to be generated by running the project", "Normal"),
             p("Abstract", "Heading1"),
             p("This project investigates whether student withdrawal risk can be identified at two points in an academic journey. Stage 1 uses information available at enrollment. Stage 2 adds early academic performance once first-semester information is available. The project analyzes two sources separately: a 4,424-record higher-education dataset with final outcomes Dropout, Enrolled, and Graduate; and the Open University Learning Analytics Dataset (OULAD), consolidated to 32,593 student-module-presentation records with Pass, Fail, Distinction, or Withdrawn outcomes. The original dataset defines Dropout as the positive class and groups Enrolled and Graduate as non-dropout. OULAD defines withdrawal from a module presentation as its positive class; this is not equivalent to leaving a university. Logistic regression, XGBoost, random forest, linear SVM, and a multilayer perceptron (MLP) are compared through stratified five-fold cross-validation. A selected soft-voting ensemble combines models based on cross-validation behavior. SHAP is used for global and individual explanations, and a Streamlit prototype presents risk screening, individual prediction, model evaluation, and feature explanations. No measured model results are included in this report because generated evaluation artifacts were absent when it was prepared."),
             p("1. Project purpose and motivation", "Heading1"),
             p("Student departure can affect learners, institutions, and the use of support resources. A useful early-warning system should estimate risk using information available at a defined point in time, so staff can consider supportive follow-up. It must also make its reasoning inspectable: a score without context is difficult to evaluate, discuss, or use responsibly."),
             p("The project studies two moments: (1) enrollment-time screening, before first-semester performance is known; and (2) an updated screening after first-semester academic results become available. Comparing these stages helps assess whether the additional academic signal improves predictive performance. This is an empirical comparison, not proof that acting on the predictions will reduce dropout."),
             p("Project objectives", "Heading2")]
    for t in ["Prepare and validate the original semicolon-delimited student dataset.", "Construct a clearly defined binary outcome for each dataset.", "Compare several classification models using consistent cross-validation within each dataset.", "Evaluate both enrollment-time and later early-warning feature sets without using later-semester fields.", "Explain model behavior with SHAP at both cohort and individual-record levels.", "Provide an interactive prototype that separates individual screening from aggregate model evaluation.", "Explore cross-dataset transfer cautiously using only a small set of harmonized fields."]:
        body.append(bullet(t))
    body += [p("2. Data sources and outcome definitions", "Heading1"),
             p("2.1 Original higher-education dataset", "Heading2"),
             p(f"The supplied data.csv file contains {len(original):,} student records and 36 input columns plus a Target field. The file is semicolon-delimited and has a wrapped/quoted header representation; the project cleaner handles the byte-order mark, quoting, and whitespace before assigning column names. The observed target counts are: Graduate {int(labels.get('Graduate',0)):,}, Dropout {int(labels.get('Dropout',0)):,}, and Enrolled {int(labels.get('Enrolled',0)):,}. The modeling target is binary: Dropout = 1; Enrolled and Graduate = 0. This grouping is a project-specific modeling choice: currently enrolled students are treated as non-dropouts at the observed outcome point, although they may not yet have completed their studies."),
             p("The original dataset has one row per student and contains no student names or identifiers suitable for real-world case management. The prototype therefore displays anonymous row references for demonstration, not identifiable students."),
             p("2.2 OULAD dataset", "Heading2"),
             p(f"OULAD consists of linked tables describing students, courses/presentations, registrations, assessments and submissions, and virtual-learning-environment activity. The consolidation script creates a student-by-module-presentation table with {len(oulad):,} rows, {oulad['code_module'].nunique()} modules, and {oulad[['code_module','code_presentation']].drop_duplicates().shape[0]} module-presentation combinations. There are no duplicate id_student + code_module + code_presentation keys in the supplied consolidated table. The observed outcome counts are Pass {int(ou_labels.get('Pass',0)):,}, Fail {int(ou_labels.get('Fail',0)):,}, Distinction {int(ou_labels.get('Distinction',0)):,}, and Withdrawn {int(ou_labels.get('Withdrawn',0)):,}. For this project's binary task, Withdrawn = 1 and Pass/Fail/Distinction = 0."),
             p("OULAD's Withdrawn label describes withdrawal from a particular module presentation. A student may withdraw from one module and continue studying elsewhere or in another presentation. It must therefore be described as module-presentation withdrawal, not university dropout. The OULAD and original targets have different meanings, populations, and units of analysis."),
             p("3. Data preparation and quality checks", "Heading1"),
             p("The cleaning script reads the original file with UTF-8 BOM handling and semicolon separation, strips whitespace from header labels, repairs the known misspellings/labels, and checks that the expected 36 inputs plus Target are present. It validates the allowed target labels and verifies that selected binary fields contain only 0/1 values. It writes cleaned_data.csv and a data_quality.json audit summary."),
             p(f"The audit summary supplied with the project reports {quality['rows']:,} rows, {quality['columns_including_target']} columns including the target, {quality['duplicate_rows']} duplicate full rows, and {quality['missing_cells']} missing cells in the original file. The observed original dataset has {orig_missing} missing input cells after parsing. The supplied OULAD consolidated data has {int(oulad.isna().sum().sum()):,} missing cells across all columns, largely in registration fields such as date_unregistration and imd_band; the model input pipelines impute missing predictors. The selected model feature columns themselves have no missing values in this supplied OULAD file, though preprocessing still includes imputers for robustness."),
             p("For OULAD, assessment/submission tables are joined to student and module-presentation records. Assessment measures are restricted to assessment dates at or before half the module-presentation length. The early aggregates include number of submitted assessments, mean score, and count at or above the script's 40-point pass rule. VLE clicks are summed only up to the same half-presentation boundary. Empty early assessment aggregates are filled with zero. These are operational definitions chosen by the project, not universal institutional rules."),
             p("4. Prediction design: two stages", "Heading1"),
             p("A feature is a model input. The feature lists are deliberately separated by the information that would be available at prediction time. No second-semester variables are used."),
             p("4.1 Original dataset feature sets", "Heading2"),
             table([["Stage", "Information point", "Inputs used"]],),
             table([["Stage 1", "At enrollment", "Admission grade; prior qualification grade; age at enrollment; course; attendance schedule; scholarship holder; debtor status; gender; education special needs."], ["Stage 2", "After first-semester results", "All Stage 1 inputs plus first-semester curricular units approved and first-semester average grade."]]),
             p("Application mode was deliberately removed from both stages and the student-entry form. Its coded admissions routes describe the source institution's context and do not have clear operational meaning for the intended Indian-facing demonstration. The source CSV remains intact for auditability, but this field is excluded from modeling."),
             p("4.2 OULAD feature sets", "Heading2"),
             table([["Stage", "Information point", "Inputs used"], ["Stage 1", "At/near registration", "Gender; region; highest education; area deprivation band; age band; previous attempts; studied credits; disability indicator; module code; presentation code."], ["Stage 2", "Early in a module presentation", "All Stage 1 inputs plus early assessments submitted, early mean assessment score, early assessments passed, and first-half VLE clicks."]]),
             p("The OULAD feature timing is not identical to the original dataset's semester timing. Its Stage 2 is an early-in-presentation window, defined as the first half of a presentation, not a university-wide first semester. Comparisons across stages are meaningful within each source under its own timing definition; they do not make the datasets interchangeable."),
             p("Leakage prevention", "Heading2"),
             p("Outcome leakage occurs when a model receives information that would only be known after the decision point or that directly encodes the outcome. Such features can make evaluation appear unrealistically strong. This project excludes second-semester measures from both original-dataset stages and uses only first-half assessment and activity aggregates for OULAD Stage 2. Final outcome labels are targets, not input features. The OULAD final result is retained only to construct the target and is not included in the feature lists."),
             p("5. Models and training procedure", "Heading1"),
             p("The model comparison script builds preprocessing and classification pipelines. Categorical inputs are imputed with the most frequent value and one-hot encoded; unknown categories at prediction time are ignored by the encoder. Numeric inputs are median-imputed and standardized. This keeps preprocessing inside each cross-validation fold and reduces leakage from fitting preprocessing statistics on held-out examples."),
             p("Models compared", "Heading2")]
    for t in ["Logistic regression: a linear baseline with balanced class weights; useful for a relatively simple, interpretable comparison.", "XGBoost: gradient-boosted decision trees with a positive-class weight based on the training-fold class balance.", "Random forest: a collection of decision trees with balanced subsampling to address class imbalance.", "Linear SVM: a linear maximum-margin classifier with balanced class weights. Its decision scores are used for ROC-AUC, while the threshold for class predictions is a zero decision score.", "MLP: a small feed-forward neural network with two hidden layers (32 and 16 units), ReLU activation, early stopping, and balanced sample weights computed on training data only.", "Soft-voting ensemble: the separate ensemble-building script fits equal-weight averages of member probability predictions. Member recipes differ by dataset and stage and are recorded in selected_ensemble_setup.json after execution."]:
        body.append(bullet(t))
    body += [p("The scripts use stratified five-fold cross-validation within each dataset, with random seed 42. Each record receives an out-of-fold prediction from a model that was not trained on that fold. For OULAD, StratifiedGroupKFold keeps all presentations belonging to the same student within one fold, reducing the risk that a student's other presentation appears in training while one appears in validation. The original dataset has one row per student and uses stratified folds."),
             p("A final model artifact is refit on all available rows for use by the website. These refitted artifacts are for demonstration/prediction; the cross-validation metrics, rather than in-sample training performance, are the intended estimate of generalization."),
             p("6. Evaluation plan and interpretation", "Heading1"),
             p("The project reports accuracy, positive-class recall, positive-class precision, and ROC-AUC. Recall is emphasized because low recall means some students who later receive the positive outcome are missed. Precision matters because a low precision can lead to many unnecessary reviews. Accuracy alone can be misleading when outcome classes are imbalanced. ROC-AUC measures ranking across thresholds; it does not select a practical review threshold by itself."),
             p("The current evaluation code uses a 0.50 threshold for probability-producing classifiers and equal-vote ensembles (and zero decision score for the linear SVM). The web app uses a 50% score as its current review threshold. This is a prototype setting, not a threshold chosen through consultation with staff, capacity constraints, or a cost-benefit analysis. Scores are explicitly not calibrated probabilities."),
             p("Stage 1 versus Stage 2 should be compared using the same folds and the same metrics within each dataset. Report the absolute metric change as Stage 2 minus Stage 1, preferably in percentage points for recall/precision/accuracy and in AUC points for ROC-AUC. An improvement in one metric may come with a decline in another, so the change should not be reduced to a single headline number."),
             p("7. Explainability with SHAP", "Heading1"),
             p("SHAP (SHapley Additive exPlanations) attributes changes in a model output to input features relative to a background/reference distribution. In this project, a global plot summarizes average absolute contributions across a sample of held-out records, helping identify features that often influence model scores. A local explanation shows how feature contributions push one record's model score above or below the reference score."),
             p("The global SHAP generation script explains selected individual models for each dataset and stage: Linear SVM for original Stage 1; logistic regression for original Stage 2 and OULAD Stage 1; XGBoost for OULAD Stage 2. Categorical one-hot contributions are grouped back to the original field. The example local explanation is selected from a held-out fold, avoiding an in-sample-only example. In the app, per-record explanations use a permutation SHAP explainer applied to the actual soft-voting ensemble. Thus the global plot and local app explanation can explain different model objects."),
             p("A positive contribution raises the model score relative to the reference; a negative contribution lowers it. SHAP explains model behavior, not real-world causes. It does not show that a feature caused a student to leave, does not establish fairness, and does not validate that a feature should be used in practice. With correlated inputs, attribution can be shared or unstable. Results depend on the model, background sample, and chosen feature set."),
             p("8. Cross-dataset analysis", "Heading1"),
             p("The code includes an exploratory train-on-one-source/test-on-the-other experiment using only two approximately harmonized inputs: gender and age group. It maps each source's gender coding and age bands into shared categories, then trains each model on one dataset and evaluates on the other. The narrow shared feature set is used because most fields have different definitions or coding systems."),
             p("This experiment is a domain-transfer stress test, not a fair head-to-head benchmark. The original positive class is institutional Dropout, while OULAD's positive class is withdrawal from a module presentation. The datasets differ in institution, time, population, record unit, and outcome. Any transfer metric must be reported with those caveats. Poor transfer does not prove that ML is ineffective; strong transfer would still require careful validation under the target institution's own labels and context."),
             p("9. Interactive application", "Heading1"),
             p("The Streamlit prototype is a staff-facing demonstration with three tabs. It is designed to separate operational screening from model-performance reporting."),
             p("Students at risk", "Heading2"),
             p("A user selects a course and whether the review point is enrollment or after first-semester data. The app scores records in that course, sorts them by score, and lists records at or above the 50% review threshold. Selecting a record displays its individual SHAP explanation. The original dataset contains no usable student identifiers; labels such as REC-00001 are dataset row references only and must not be mistaken for real student identities."),
             p("Prediction", "Heading2"),
             p("A user enters a single record's enrollment inputs. For Stage 2, they also enter first-semester approved units and grade. The model returns its ensemble score, threshold status, and SHAP table showing which inputs raised or lowered that model score. An optional institution reference is displayed but is not persisted by the app. The page states that the score is not a calibrated probability and that SHAP associations are not causes."),
             p("Model results", "Heading2"),
             p("This tab presents the cross-validation model comparison for the chosen dataset and stage, identifies the selected ensemble members, displays recall and ROC-AUC visual comparisons, and provides the exploratory cross-dataset results. It also shows global and held-out example SHAP plots. These aggregate evaluation results are intentionally separate from a single student's prediction."),
             p("10. How to run the project", "Heading1"),
             p("The project is intended to run locally on Windows using Python. The supplied datasets and source scripts are in one project directory. Running the wrapper prepares cleaned data, performs model comparisons if outputs are missing or stale, fits the selected ensembles, generates SHAP plots, then starts the Streamlit app. First run may take several minutes because cross-validation, model fitting, and SHAP generation are computed locally."),
             p("Steps", "Heading2")]
    for t in ["Install Python 3 and open PowerShell in the project directory.", "Install packages: py -m pip install -r requirements.txt.", "Run: py run_app.py (or double-click start_dashboard.bat).", "Wait for model preparation to finish. The browser opens the local website.", "For later code changes, rerun the wrapper; generated model and result files are local outputs and are excluded from Git by .gitignore."]:
        body.append(bullet(t))
    body += [p("11. Results", "Heading1"),
             p("No generated cross-validation tables, selected ensemble metrics, model artifacts, or SHAP plots were present in the project results directory when this report was created. Therefore, this report does not claim numeric accuracy, recall, precision, ROC-AUC, or a measured Stage 2 improvement. Those values must be populated from the app's Model results tab or the generated results/dataset_comparison/within_dataset_cv.csv and selected_ensemble_metrics.csv after running the project."),
             table([["Dataset", "Stage", "Model / ensemble", "Accuracy", "Positive recall", "Positive precision", "ROC-AUC"], ["Original", "Stage 1", "Pending run", "—", "—", "—", "—"], ["Original", "Stage 2", "Pending run", "—", "—", "—", "—"], ["OULAD", "Stage 1", "Pending run", "—", "—", "—", "—"], ["OULAD", "Stage 2", "Pending run", "—", "—", "—", "—"]]),
             p("Stage 2 improvement: calculate the Stage 2 metric minus Stage 1 for each dataset after evaluation. Do not assume an improvement before viewing the measured results."),
             p("12. Limitations, ethics, and responsible use", "Heading1")]
    for t in ["Outcome definitions are imperfect proxies. Enrolled is grouped with Graduate as non-dropout in the original dataset, and OULAD Withdrawn is only module-presentation withdrawal.", "The source institutions and populations may differ from the intended deployment context. A model trained on historical data may not generalize to a different country, institution, curriculum, or time period.", "Feature availability and definitions must be confirmed at each prediction point. Debtor or scholarship status may change over time; using it can create timing, fairness, and policy concerns.", "Protected or sensitive attributes such as gender, disability/special-needs status, and area-deprivation proxies require careful legal, ethical, and fairness review before operational use. Historical patterns may encode structural inequities.", "The 50% threshold is a demonstration default. Operational thresholds need staff input, capacity planning, calibration assessment, and explicit consideration of false negatives and false positives.", "A model flag should prompt a supportive human review, not an adverse decision, punishment, denial of services, or an assumption that a student will leave.", "SHAP is a model explanation method, not a causal method and not a fairness certificate.", "The app is a research prototype. It has no authentication, access controls, auditable case management, institution data integration, monitoring, or production privacy controls. Do not enter real student data into an unapproved environment.", "The risk-list page demonstrates ranking but, because the supplied dataset lacks identities, cannot directly support contacting students.", "Five-fold cross-validation estimates performance under the source dataset's sampling structure; it does not replace external validation, temporal validation, prospective testing, or a controlled evaluation of interventions."]:
        body.append(bullet(t))
    body += [p("13. Recommended next steps", "Heading1")]
    for t in ["Run the full project and save the generated metric tables, ensemble setup, and SHAP figures.", "Review per-class confusion matrices and precision-recall curves; select a review threshold with stakeholders rather than relying only on 0.50.", "Quantify Stage 2 changes separately for every metric and dataset, and state any trade-offs.", "Check subgroup performance and calibration where sample sizes allow; document limitations and avoid unfair use.", "Validate on later cohorts or an external institution before any real deployment.", "Replace anonymous row references with a secure, authorized identifier linkage only if the project is approved for a real operational environment.", "Review the feature meanings and data timing with institutional staff, especially fields whose status can change during study."]:
        body.append(bullet(t))
    body += [p("14. Glossary", "Heading1"),
             table([["Term", "Meaning in this report"], ["Feature", "An input column used by a model to estimate the target."], ["Target / label", "The outcome the model is trained to predict."], ["Positive class", "The outcome encoded as 1: Dropout in the original data; module-presentation Withdrawn in OULAD."], ["Recall", "Among truly positive records, the fraction the model identifies."], ["Precision", "Among records flagged positive by the model, the fraction truly positive."], ["ROC-AUC", "A threshold-independent measure of ranking separation between classes; 0.5 is chance-level ranking."], ["Cross-validation", "Repeated train/validation evaluation across folds so each record is evaluated out of fold."], ["Data leakage", "Use of information unavailable at the intended prediction time or derived from the outcome."], ["Soft voting", "Averaging class probability scores from multiple fitted models."], ["SHAP", "A method to attribute model output differences to input features relative to a reference."], ["Calibration", "Agreement between predicted probabilities and observed event frequencies."], ["OULAD", "Open University Learning Analytics Dataset containing student, module, assessment, and online activity data."]]),
             p("Appendix A. Project files", "Heading1"),
             table([["File", "Purpose"], ["clean_data.py", "Cleans and validates the original semicolon-delimited dataset and writes an audit summary."], ["consolidate_oulad.py", "Combines linked OULAD tables into early-window student-presentation records."], ["compare_datasets.py", "Defines features, preprocessing, model configurations, five-fold comparisons, and exploratory transfer evaluation."], ["build_ensembles.py", "Builds selected soft-voting ensembles, records their members and feature manifests, and writes CV metrics."], ["make_comparison_shap.py", "Creates global and held-out example SHAP plots for selected models."], ["app.py", "Implements the Streamlit risk screening, single-record prediction, model results, and SHAP interface."], ["run_app.py", "Prepares cleaned data and missing/stale model assets before launching Streamlit."], ["requirements.txt", "Lists Python package dependencies."], ["data.csv", "Original higher-education input data."], ["oulad_student_level.csv", "Consolidated OULAD student-module-presentation data used by the project."]]),
             p("Appendix B. Interpretation note", "Heading1"),
             p("This report describes the code and datasets present in the project directory. Statements about feature lists, preprocessing, and evaluation settings are based on the source code. Data counts are computed from the supplied datasets or the cleaning audit. No model-performance values are asserted without generated evaluation output. Before presenting the project, run the pipeline and replace the pending results table with the actual cross-validation figures. Include the generated SHAP plots if the report is intended to contain visual evidence.")]
    return ''.join(body)


def main():
    original, oulad, quality, labels, ou_labels = run_info()
    body = build_body(original, oulad, quality, labels, ou_labels)
    TEMP.mkdir(exist_ok=True)
    document = f'''<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>{body}<w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1100" w:right="1100" w:bottom="1100" w:left="1100"/><w:cols w:space="720"/><w:docGrid w:linePitch="360"/></w:sectPr></w:body></w:document>'''
    styles = '''<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
<w:docDefaults><w:rPrDefault><w:rPr><w:rFonts w:ascii="Aptos" w:hAnsi="Aptos"/><w:sz w:val="21"/><w:color w:val="443832"/></w:rPr></w:rPrDefault><w:pPrDefault><w:pPr><w:spacing w:after="120" w:line="280"/></w:pPr></w:pPrDefault></w:docDefaults>
<w:style w:type="paragraph" w:default="1" w:styleId="Normal"><w:name w:val="Normal"/><w:rPr><w:rFonts w:ascii="Aptos" w:hAnsi="Aptos"/><w:sz w:val="21"/></w:rPr></w:style>
<w:style w:type="paragraph" w:styleId="Title"><w:name w:val="Title"/><w:pPr><w:spacing w:before="1200" w:after="250"/><w:jc w:val="center"/></w:pPr><w:rPr><w:b/><w:rFonts w:ascii="Aptos Display" w:hAnsi="Aptos Display"/><w:sz w:val="38"/><w:color w:val="C85F49"/></w:rPr></w:style>
<w:style w:type="paragraph" w:styleId="Subtitle"><w:name w:val="Subtitle"/><w:pPr><w:jc w:val="center"/><w:spacing w:after="200"/></w:pPr><w:rPr><w:i/><w:sz w:val="25"/><w:color w:val="806A60"/></w:rPr></w:style>
<w:style w:type="paragraph" w:styleId="Heading1"><w:name w:val="heading 1"/><w:basedOn w:val="Normal"/><w:next w:val="Normal"/><w:qFormat/><w:pPr><w:keepNext/><w:spacing w:before="300" w:after="130"/><w:outlineLvl w:val="0"/></w:pPr><w:rPr><w:b/><w:sz w:val="30"/><w:color w:val="C85F49"/></w:rPr></w:style>
<w:style w:type="paragraph" w:styleId="Heading2"><w:name w:val="heading 2"/><w:basedOn w:val="Normal"/><w:next w:val="Normal"/><w:qFormat/><w:pPr><w:keepNext/><w:spacing w:before="220" w:after="100"/><w:outlineLvl w:val="1"/></w:pPr><w:rPr><w:b/><w:sz w:val="24"/><w:color w:val="9C503E"/></w:rPr></w:style>
</w:styles>'''
    content_types = '''<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/><Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/></Types>'''
    rels = '''<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>'''
    doc_rels = '''<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rIdStyles" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>'''
    with ZipFile(OUT, 'w', ZIP_DEFLATED) as z:
        z.writestr('[Content_Types].xml', content_types)
        z.writestr('_rels/.rels', rels)
        z.writestr('word/document.xml', document)
        z.writestr('word/styles.xml', styles)
        z.writestr('word/_rels/document.xml.rels', doc_rels)
    print(f"Created: {OUT}")
    print(f"Paragraphs: {body.count('<w:p>'):,}; tables: {body.count('<w:tbl>')}")


if __name__ == '__main__':
    main()
